// Input Parameters (Units: seconds, RPM, Bytes, B/s)
float T_seek_avg;
float R_rpm;
float B_size;
float R_rate_Bps;

#define SEC_PER_MIN 60.0f

// 1. Rotational Latency (T_latency)
// Average case: 1/2 rotation time
float T_latency = 0.5f * (SEC_PER_MIN / R_rpm);

// 2. Data Transfer Time (T_transfer)
// Size / Rate
float T_transfer = B_size / R_rate_Bps;

// Total Disk Access Time (T_access)
// T_access = T_seek + T_latency + T_transfer
float T_access = T_seek_avg + T_latency + T_transfer;
